window.GUIDE_TRACKS=[{"title":"Всё начинается с идеи","category":"ЗНАКОМСТВО","description":"Первая точка твоего путешествия","audio":"audio/01.m4a","demo":true,"transcript":"Привет! Ты на выставке Мегабаттла. Здесь у каждой истории свой голос. Это демонстрационная запись первой точки. Оглянись вокруг: любая большая история начинается с одной идеи. Чтобы услышать следующий голос, нажми на сканер и наведи камеру на код у следующего экспоната.","cover":"covers/awake.jpg","coverAlt":"Обложка Tycho — Awake"},{"title":"Люди за кадром","category":"СОЗДАТЕЛИ","description":"Те, кто превращает замысел в реальность","audio":"audio/02.m4a","demo":true,"transcript":"Ты слышишь второй голос выставки. Это демонстрация истории о людях за кадром. За каждым событием стоят те, кто придумывает, собирает, пробует и начинает снова. Здесь будет ваша запись о создателях экспоната.","cover":"covers/kiasmos.jpg","coverAlt":"Обложка Kiasmos — Kiasmos"},{"title":"Энергия команды","category":"ВМЕСТЕ","description":"Когда разные голоса звучат в унисон","audio":"audio/03.m4a","demo":true,"transcript":"Это третий рассказчик. Перед тобой демонстрационная точка об энергии команды. Разные идеи, разные люди, один общий ритм. Именно так рождается Мегабаттл. Здесь прозвучит записанная вами история.","cover":"covers/immunity.jpg","coverAlt":"Обложка Jon Hopkins — Immunity"},{"title":"История продолжается","category":"НОВАЯ ГЛАВА","description":"Теперь ты тоже часть этой истории","audio":"audio/04.m4a","demo":true,"transcript":"Ты у четвёртой точки выставки. Это тестовый голос финальной истории. Выставка заканчивается, но история продолжается в тех, кто побывал здесь. Спасибо, что слушаешь. Ты можешь вернуться к любой точке и открыть её заново.","cover":"covers/migration.jpg","coverAlt":"Обложка Bonobo — Migration"}];
